def normalized(self):
    normalized_days = int(self.days)
    normalized_hours = int(self.hours)
    normalized_minutes = int(self.minutes)
    normalized_seconds = int(self.seconds)

    # normalize the days
    if self.days != normalized_days and (self.hours > 0 or self.minutes > 0 or self.seconds > 0):
        normalized_days += 1
        while normalized_hours <= 23:
            normalized_hours += 1

    # normalize the hours
    if self.hours != normalized_hours and (self.minutes > 0 or self.seconds > 0):
        normalized_hours += 1
        while normalized_minutes <= 59:
            normalized_minutes += 1

    # normalize the minutes
    if self.minutes != normalized_minutes and self.seconds > 0:
        normalized_minutes += 1
        while normalized_seconds <= 59:
            normalized_seconds += 1

    # normalize the seconds
    if self.seconds != normalized_seconds:
        normalized_seconds += 1

    return relativedelta(days=normalized_days, hours=normalized_hours, minutes=normalized_minutes, seconds=normalized_seconds)

