def deep_merge_nodes(nodes):
    '''
    Given a list of tuples of (key node, value node), deep merge any node values corresponding
    to duplicate keys and return the result. If there are colliding keys with non-MappingNode
    values (e.g., integers or strings), the last of the values wins.
    '''
    # Initialize result list
    result = []

    # Iterate over each node tuple
    for key_node, value_node in nodes:
        # Check if current key node is already in result list
        for i, (result_key_node, _) in enumerate(result):
            # If key nodes match, deep merge value nodes and update result at that index
            if key_node == result_key_node:
                result[i] = (result_key_node, deep_merge_nodes((value_node, result_value_node)))
                break
        # If key node is not in result list, add entire node tuple to result
        else:
            result.append((key_node, value_node))

    return result

# Helper function for deep merging nodes
def deep_merge_nodes(nodes):
    key_nodes, value_nodes = zip(*nodes)
    # If all value nodes are MappingNodes, return merged MappingNode
    if all(isinstance(node, ruamel.yaml.nodes.MappingNode) for node in value_nodes):
        return ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map',
                                             value=deep_merge_mappings(value_nodes))
    # If all value nodes are ScalarNodes with the same tag, return last node
    elif all(isinstance(node, ruamel.yaml.nodes.ScalarNode) and node.tag == value_nodes[0].tag
             for node in value_nodes):
        return value_nodes[-1]
    # Otherwise, raise ValueError
    else:
        raise ValueError("Cannot deep merge nodes with different types or tags")

# Helper function for merging MappingNodes
def deep_merge_mappings(mappings):
    result = {}
    for mapping in mappings:
        result.update(mapping.value)
    return {key: deep_merge_nodes((value, result.get(key)))
            for key, value in result.items()}

