def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise ValueError("dic must be a dictionary")
    if not isinstance(val, str):
        raise ValueError("val must be a string")
    if not isinstance(key, str) or "." not in key:
        raise ValueError("key must be a string in the format 'key1.key2.key3'")
    if keys:
        if not all(isinstance(k, str) and "." in k for k in keys):
            raise ValueError("The keys in keys must be strings in the format 'key1.key2.key3'")
    current_key = key
    for k in keys:
        if current_key in dic:
            if isinstance(dic[current_key], dict):
                dic = dic[current_key]
            else:
                raise ValueError(f"key '{current_key}' is not a valid key in the dictionary")
        else:
            raise ValueError(f"key '{current_key}' is not a key in the dictionary")
        current_key = k
    dic[current_key] = val
    return dic
