def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = {}
    try:
        with open(os.path.join(plugin_dir, "plugin.json"), "r") as f:
            plugin_spec = json.load(f)
    except FileNotFoundError as e:
        raise ValueError(f"plugin.json not found in {plugin_dir}") from e
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON data in plugin.json") from e

    flat_spec = {}
    for k, v in plugin_spec.items():
        if isinstance(v, dict):
            for sub_k, sub_v in v.items():
                flat_spec[f"{k}.{sub_k}"] = sub_v
        else:
            flat_spec[k] = v

    return flat_spec
